Here is the commit message:
net/sched: sch_qfq: do not free existing class in
 qfq_change_class()

Fixes qfq_change_class() error case.

cl->qdisc and cl should only be freed if a new class and qdisc
were allocated, or we risk various UAF.

Fixes: 462dbc9101ac ("pkt_sched: QFQ Plus: fair-queueing service at DRR cost")
Reported-by: syzbot+07f3f38f723c335f106d@syzkaller.appspotmail.com
Closes: https://lore.kernel.org/netdev/6965351d.050a0220.eaf7.00c5.GAE@google.com/T/#u
Signed-off-by: Eric Dumazet <edumazet@google.com>
Reviewed-by: Jamal Hadi Salim <jhs@mojatatu.com>
Link: https://patch.msgid.link/20260112175656.17605-1-edumazet@google.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
In qfq_change_class(), the error path at label `destroy_class` unconditionally frees `cl` and `cl->qdisc` regardless of whether the class was newly allocated (`existing == false`) or already existed (`existing == true`). When a class already exists, freeing its memory while it is still in use causes a use-after-free vulnerability.

Here is the patch:

 static int qfq_change_class(struct Qdisc *sch, u32 classid, u32 parentid,
 			    struct nlattr **tca, unsigned long *arg,
 			    struct netlink_ext_ack *extack)
 {
 	struct qfq_sched *q = qdisc_priv(sch);
 	struct qfq_class *cl = (struct qfq_class *)*arg;
 	bool existing = false;
 	struct nlattr *tb[TCA_QFQ_MAX + 1];
 	struct qfq_aggregate *new_agg = NULL;
 	u32 weight, lmax, inv_w, old_weight, old_lmax;
 	int err;
 	int delta_w;

 	if (NL_REQ_ATTR_CHECK(extack, NULL, tca, TCA_OPTIONS)) {
 		NL_SET_ERR_MSG_MOD(extack, "missing options");
 		return -EINVAL;
 	}

 	err = nla_parse_nested_deprecated(tb, TCA_QFQ_MAX, tca[TCA_OPTIONS],
 					  qfq_policy, extack);
 	if (err < 0)
 		return err;

 	weight = nla_get_u32_default(tb[TCA_QFQ_WEIGHT], 1);

 	if (tb[TCA_QFQ_LMAX]) {
 		lmax = nla_get_u32(tb[TCA_QFQ_LMAX]);
 	} else {
 		/* MTU size is user controlled */
 		lmax = psched_mtu(qdisc_dev(sch));
 		if (lmax < QFQ_MIN_LMAX || lmax > QFQ_MAX_LMAX) {
 			NL_SET_ERR_MSG_MOD(extack,
 					   "MTU size out of bounds for qfq");
 			return -EINVAL;
 		}
 	}

 	inv_w = ONE_FP / weight;
 	weight = ONE_FP / inv_w;

 	if (cl != NULL) {
 		sch_tree_lock(sch);
 		old_weight = cl->agg->class_weight;
 		old_lmax   = cl->agg->lmax;
 		sch_tree_unlock(sch);
 		if (lmax == old_lmax && weight == old_weight)
 			return 0; /* nothing to change */
 	}

 	delta_w = weight - (cl ? old_weight : 0);

 	if (q->wsum + delta_w > QFQ_MAX_WSUM) {
 		NL_SET_ERR_MSG_FMT_MOD(extack,
 				       "total weight out of range (%d + %u)",
 				       delta_w, q->wsum);
 		return -EINVAL;
 	}

 	if (cl != NULL) { /* modify existing class */
 		if (tca[TCA_RATE]) {
 			err = gen_replace_estimator(&cl->bstats, NULL,
 						    &cl->rate_est,
 						    NULL,
 						    true,
 						    tca[TCA_RATE]);
 			if (err)
 				return err;
 		}
 		existing = true;
 		goto set_change_agg;
 	}

 	/* create and init new class */
 	cl = kzalloc(sizeof(struct qfq_class), GFP_KERNEL);
 	if (cl == NULL)
 		return -ENOBUFS;

 	gnet_stats_basic_sync_init(&cl->bstats);
 	cl->common.classid = classid;
 	cl->deficit = lmax;
 	INIT_LIST_HEAD(&cl->alist);

 	cl->qdisc = qdisc_create_dflt(sch->dev_queue, &pfifo_qdisc_ops,
 				      classid, NULL);
 	if (cl->qdisc == NULL)
 		cl->qdisc = &noop_qdisc;

 	if (tca[TCA_RATE]) {
 		err = gen_new_estimator(&cl->bstats, NULL,
 					&cl->rate_est,
 					NULL,
 					true,
 					tca[TCA_RATE]);
 		if (err)
 			goto destroy_class;
 	}

 	if (cl->qdisc != &noop_qdisc)
 		qdisc_hash_add(cl->qdisc, true);

 set_change_agg:
 	sch_tree_lock(sch);
 	new_agg = qfq_find_agg(q, lmax, weight);
 	if (new_agg == NULL) { /* create new aggregate */
 		sch_tree_unlock(sch);
 		new_agg = kzalloc(sizeof(*new_agg), GFP_KERNEL);
 		if (new_agg == NULL) {
 			err = -ENOBUFS;
 			gen_kill_estimator(&cl->rate_est);
 			goto destroy_class;
 		}
 		sch_tree_lock(sch);
 		qfq_init_agg(q, new_agg, lmax, weight);
 	}
 	if (existing)
 		qfq_deact_rm_from_agg(q, cl);
 	else
 		qdisc_class_hash_insert(&q->clhash, &cl->common);
 	qfq_add_to_agg(q, new_agg, cl);
 	sch_tree_unlock(sch);
 	qdisc_class_hash_grow(sch, &q->clhash);

 	*arg = (unsigned long)cl;
 	return 0;

 destroy_class:
-	qdisc_put(cl->qdisc);
-	kfree(cl);
+	if (!existing) {
+		qdisc_put(cl->qdisc);
+		kfree(cl);
+	}
 	return err;
 }



